import { useState } from 'react';

export default function WaitlistForm() {
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setStatus('loading');

    const formData = new FormData(e.currentTarget);

    try {
      const response = await fetch('https://api.forms.bucksaas.com/s/a7e0a044-9aef-43ed-a713-7265364bb1c4', {
        method: 'POST',
        body: formData,
        headers: {
          'Accept': 'application/json'
        }
      });

      if (response.ok) {
        setStatus('success');
      } else {
        setStatus('error');
      }
    } catch (error) {
      setStatus('error');
    }
  };

  if (status === 'success') {
    return (
      <div className="w-full max-w-xl mx-auto p-10 bg-[#111] border border-emerald-500/30 text-center">
        <h3 className="text-[24px] font-serif text-white mb-4">Request Received</h3>
        <p className="text-[16px] text-emerald-400 font-mono">
          You are on the list. We will contact you when a slot opens for your team.
        </p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="w-full max-w-2xl mx-auto flex flex-col gap-6 text-left">
      {status === 'error' && (
        <div className="p-4 bg-red-500/10 border border-red-500/30 text-red-400 font-mono text-[12px] uppercase tracking-widest text-center">
          Failed to submit. Please try again.
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="flex flex-col gap-2">
          <label className="text-[11px] font-mono text-white/50 uppercase tracking-widest">Full Name *</label>
          <input 
            type="text" 
            name="name" 
            required 
            className="px-5 py-4 bg-white/5 border border-white/20 text-white placeholder-white/20 text-[14px] font-mono focus:outline-none focus:border-white transition-colors w-full"
            placeholder="Jane Doe"
          />
        </div>
        <div className="flex flex-col gap-2">
          <label className="text-[11px] font-mono text-white/50 uppercase tracking-widest">Work Email *</label>
          <input 
            type="email" 
            name="email" 
            required 
            className="px-5 py-4 bg-white/5 border border-white/20 text-white placeholder-white/20 text-[14px] font-mono focus:outline-none focus:border-white transition-colors w-full"
            placeholder="jane@company.com"
          />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="flex flex-col gap-2">
          <label className="text-[11px] font-mono text-white/50 uppercase tracking-widest">Company / Org *</label>
          <input 
            type="text" 
            name="company" 
            required 
            className="px-5 py-4 bg-white/5 border border-white/20 text-white placeholder-white/20 text-[14px] font-mono focus:outline-none focus:border-white transition-colors w-full"
            placeholder="Acme Corp"
          />
        </div>
        <div className="flex flex-col gap-2">
          <label className="text-[11px] font-mono text-white/50 uppercase tracking-widest">Team Size</label>
          <select 
            name="team_size" 
            className="px-5 py-4 bg-white/5 border border-white/20 text-white text-[14px] font-mono focus:outline-none focus:border-white transition-colors w-full appearance-none"
          >
            <option value="1-10" className="bg-[#111]">1 - 10 Engineers</option>
            <option value="11-50" className="bg-[#111]">11 - 50 Engineers</option>
            <option value="50+" className="bg-[#111]">50+ Engineers</option>
          </select>
        </div>
      </div>

      <div className="flex flex-col gap-2">
        <label className="text-[11px] font-mono text-white/50 uppercase tracking-widest">How are you using AI agents today?</label>
        <textarea 
          name="use_case" 
          rows={3}
          className="px-5 py-4 bg-white/5 border border-white/20 text-white placeholder-white/20 text-[14px] font-mono focus:outline-none focus:border-white transition-colors w-full resize-none"
          placeholder="e.g. We use Cursor heavily but struggle with massive PR reviews..."
        ></textarea>
      </div>

      <button 
        type="submit" 
        disabled={status === 'loading'}
        className="mt-4 w-full py-5 border border-white bg-white text-black text-[13px] font-mono uppercase tracking-[0.2em] font-bold hover:bg-transparent hover:text-white transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
      >
        {status === 'loading' ? 'Submitting...' : 'Request Invite'}
      </button>
    </form>
  );
}
